// Банк по мотивам сборника Сканави, порция 4: планиметрия и стереометрия
// (главы 10–12). Это параметрические шаблоны: числа в каждом задании
// случайные, ответ считается в коде, поэтому один шаблон даёт много разных
// задач. Тексты на двух языках, чертёж не требуется.
import type { Template } from '../helpers'
import { c, h, N, T as T0, pick, rnd, frac, gcd, type B } from './bi'

// Варианты без повторов: совпавшие заменяются соседними значениями верного ответа
const key = (x: B | string) => (typeof x === 'string' ? x : x[0])
const bump = (r: string, i: number) => (/\d/.test(r) ? r.replace(/\d+/, m => String(+m + i)) : r.replace('$', `$${i + 1}`))
const T = (q: B, right: B | string, wrongs: (B | string)[], n: number, sol: B | string) => {
  const seen = new Set([key(right)]), w: (B | string)[] = []
  for (const x of wrongs) if (!seen.has(key(x))) { seen.add(key(x)); w.push(x) }
  for (let i = 1; typeof right === 'string' && w.length < 4 && i < 40; i++) { const x = bump(right, i); if (!seen.has(x)) { seen.add(x); w.push(x) } }
  return T0(q, right, w, n, sol)
}
const Q = (ru: string, kk: string): B => [ru, kk]
// kπ, где k может быть дробью p/q
const Pf = (p: number, q = 1) => { const f = frac(p, q); return `$${f === '1' ? '' : f}\\pi$` }
// k√m
const Rt = (k: number, m: number) => `$${k === 1 ? '' : k}\\sqrt{${m}}$`
// Пифагоровы тройки и «тройки» для диагонали параллелепипеда (a, b, c, d)
const TR: [number, number, number][] = [[3, 4, 5], [5, 12, 13], [8, 15, 17], [7, 24, 25], [20, 21, 29], [9, 40, 41]]
const TR3: [number, number, number, number][] = [[1, 2, 2, 3], [2, 3, 6, 7], [1, 4, 8, 9], [2, 6, 9, 11], [4, 4, 7, 9], [6, 6, 7, 11]]
const tri = (k = rnd(1, 3)) => { const [a, b, cc] = pick(TR); return [a * k, b * k, cc * k] }
const D = '°', CM = 'см', CM2 = 'см²', CM3 = 'см³'

