const A7 = 'Подобие треугольников', A8 = 'Медианы, биссектрисы, высоты', A9 = 'Длина дуги. Площадь сектора'
const A10 = 'Площади фигур', A11 = 'Теоремы синусов и косинусов', A12 = 'Правильные многоугольники. Вписанные и описанные'
